===== README.md =====
     1	# ledgerline
     2	
     3	Nightly jobs that export ledger entries to the reporting warehouse and import adjustments
     4	back. Configuration is loaded by `src/config/load.js`.
===== package.json =====
     1	{
     2	  "name": "ledgerline-fixture",
     3	  "version": "1.0.0",
     4	  "private": true,
     5	  "description": "Nightly ledger export and import jobs",
     6	  "main": "src/jobs/export.js",
     7	  "type": "commonjs"
     8	}
===== config/production.json =====
     1	{
     2	  "export": {
     3	    "timeoutMs": 30000
     4	  }
     5	}
===== config/staging.json =====
     1	{
     2	  "export": {
     3	    "retryLimit": 5,
     4	    "timeoutMs": 20000
     5	  }
     6	}
===== src/config/limits.js =====
     1	'use strict';
     2	
     3	// Production caps agreed with the warehouse team. They apply after every override.
     4	module.exports = {
     5	  production: {
     6	    maxExportRetries: 2,
     7	  },
     8	};
===== src/config/load.js =====
     1	'use strict';
     2	
     3	const fs = require('fs');
     4	const path = require('path');
     5	const defaults = require('./defaults');
     6	const limits = require('./limits');
     7	
     8	function readEnvironmentFile(envName) {
     9	  const file = path.join(__dirname, '..', '..', 'config', `${envName}.json`);
    10	  if (!fs.existsSync(file)) return {};
    11	  return JSON.parse(fs.readFileSync(file, 'utf8'));
    12	}
    13	
    14	function fromVariables(env) {
    15	  const out = { export: {} };
    16	  if (env.LEDGER_EXPORT_RETRIES) out.export.retryLimit = Number(env.LEDGER_EXPORT_RETRIES);
    17	  if (env.LEDGER_EXPORT_TIMEOUT_MS) out.export.timeoutMs = Number(env.LEDGER_EXPORT_TIMEOUT_MS);
    18	  return out;
    19	}
    20	
    21	function merge(...layers) {
    22	  const result = { export: {}, import: {} };
    23	  for (const layer of layers) {
    24	    Object.assign(result.export, layer.export);
    25	    Object.assign(result.import, layer.import);
    26	  }
    27	  return result;
    28	}
    29	
    30	function load(env = process.env) {
    31	  const envName = env.NODE_ENV || 'development';
    32	  const config = merge(defaults, readEnvironmentFile(envName), fromVariables(env));
    33	  const caps = limits[envName];
    34	  if (caps) {
    35	    config.export.retryLimit = Math.min(config.export.retryLimit, caps.maxExportRetries);
    36	  }
    37	  return config;
    38	}
    39	
    40	module.exports = { load };
===== src/config/defaults.js =====
     1	'use strict';
     2	
     3	module.exports = {
     4	  export: {
     5	    retryLimit: 3,
     6	    timeoutMs: 10000,
     7	  },
     8	  import: {
     9	    timeoutMs: 15000,
    10	  },
    11	};
===== src/jobs/export.js =====
     1	'use strict';
     2	
     3	const { load } = require('../config/load');
     4	
     5	async function withRetries(fn, { retryLimit, timeoutMs }) {
     6	  let lastError;
     7	  for (let attempt = 0; attempt <= retryLimit; attempt += 1) {
     8	    try {
     9	      return await fn({ timeoutMs });
    10	    } catch (error) {
    11	      lastError = error;
    12	    }
    13	  }
    14	  throw lastError;
    15	}
    16	
    17	async function runExport(sendBatch) {
    18	  const config = load();
    19	  return withRetries(sendBatch, {
    20	    retryLimit: config.export.retryLimit,
    21	    timeoutMs: config.export.timeoutMs,
    22	  });
    23	}
    24	
    25	module.exports = { runExport, withRetries };
===== src/jobs/import.js =====
     1	'use strict';
     2	
     3	const { load } = require('../config/load');
     4	const { withRetries } = require('./export');
     5	
     6	async function runImport(fetchAdjustments) {
     7	  const config = load();
     8	  return withRetries(fetchAdjustments, {
     9	    retryLimit: 5,
    10	    timeoutMs: config.import.timeoutMs,
    11	  });
    12	}
    13	
    14	module.exports = { runImport };

